/bin/bash -lc "cat > /tmp/catalog-browser-check/check.mjs <<'EOF'
import assert from 'node:assert/strict'
import { chromium } from 'playwright'

const browser = await chromium.launch({ headless: true })
try {
  const context = await browser.newContext()
  const page = await context.newPage()
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  const categories = [
    { slug: 'featured', heading: 'Featured products', products: ['Desk Lamp', 'Wool Blanket'] },
    { slug: 'sale', heading: 'Products on sale', products: ['Canvas Tote', 'Travel Mug'] },
  ]
  const prefetched = new Set()
  page.on('response', async response => {
    const url = new URL(response.url())
    if (url.pathname "'!== '"'/catalog' || "'!response.request().headers()['"'next-router-prefetch']) return
    try {
      const body = await response.text()
      for (const category of categories) {
        if (url.searchParams.get('category') === category.slug &&
            body.includes(category.heading) && category.products.every(product => body.includes(product))) {
          prefetched.add(category.slug)
        }
      }
    } catch {}
  })
  await page.goto('http://127.0.0.1:3000/')
  for (const category of categories) {
    assert.equal(await page.getByRole('link', { name: category.heading }).getAttribute('href'), "'`/catalog?category=${category.slug}`)
  }
  const deadline = Date.now() + 15_000
  while (prefetched.size < categories.length && Date.now() < deadline) {
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  assert.equal(prefetched.size, categories.length, '"'Both URL-specific headings and product lists must arrive before clicking')
  await page.waitForLoadState('networkidle')
  await context.setOffline(true)
  await page.evaluate(() => {
    window.loadingAppeared = false
    new MutationObserver(records => {
      for (const record of records) {
        for (const node of record.addedNodes) {
          if (node.textContent?.includes('Loading category...')) window.loadingAppeared = true
        }
      }
    }).observe(document.body, { subtree: true, childList: true })
  })
  for (const category of categories) {
    const started = Date.now()
    await page.getByRole('link', { name: category.heading }).click()
    await page.getByRole('heading', { name: category.heading, exact: true }).waitFor({ timeout: 1500 })
    assert.equal(new URL(page.url()).pathname + new URL(page.url()).search, "'`/catalog?category=${category.slug}`)
    assert.deepEqual(await page.locator('"'section li').allTextContents(), category.products)
    assert.equal(await page.evaluate(() => window.loadingAppeared), false, 'Loading fallback must never be inserted during prefetched navigation')
    console.log("'`PASS: ${category.slug} navigated offline with correct heading/products and no fallback (${Date.now() - started}ms)`)
    await page.goBack()
    await page.getByRole('"'heading', { name: 'Shop by category' }).waitFor()
  }
  assert.deepEqual(errors, [])
  await context.setOffline(false)
  await page.goto('http://127.0.0.1:3000/catalog')
  await page.getByRole('heading', { name: 'Featured products', exact: true }).waitFor()
  assert.deepEqual(await page.locator('section li').allTextContents(), categories[0].products)
  console.log('PASS: direct /catalog visit retains featured default')
} finally {
  await browser.close()
}
EOF
node /tmp/catalog-browser-check/check.mjs"

/bin/bash -lc "cat > /tmp/catalog-browser-check/trace.mjs <<'EOF'
import { chromium } from 'playwright'
const browser = await chromium.launch()
const page = await browser.newPage()
page.on('console', message => console.log('CONSOLE', message.type(), message.text()))
page.on('pageerror', error => console.log('ERROR', error.message))
page.on('requestfailed', request => console.log('FAILED', request.url(), request.failure()))
page.on('request', request => {
  if (new URL(request.url()).pathname === '/catalog') console.log('REQUEST', request.url(), request.headers())
})
page.on('response', async response => {
  if (new URL(response.url()).pathname "'!== '"'/catalog') return
  console.log('RESPONSE', response.status(), response.url())
  try {console.log('BODY', response.url(), (await response.text()).slice(-2000))} catch(error) {console.log('BODY ERROR', error.message)}
})
await page.goto('http://127.0.0.1:3000/')
await page.waitForTimeout(5000)
await page.getByRole('link', { name: 'Products on sale' }).click()
await page.waitForTimeout(1500)
console.log('CONTENT', await page.locator('body').innerText())
await browser.close()
EOF
node /tmp/catalog-browser-check/trace.mjs"
